Generate documentation for this C function:

**Function**: arrayToString

```c
// C program for the function called arrayToString
// Contains target function implementation and dependency signatures

#include <stdio.h>    /// for IO operations
#include <stdlib.h>   /// for dynamic memory allocation
#include <string.h>   /// for string operations
#include <inttypes.h> /// for uint8_t, int8_t

// Target function implementation
int arrayToString(const int8_t *arr, uint8_t size, char *buffer, size_t buffer_size)
{
    if (buffer == NULL || buffer_size == 0)
    {
        return -1;
    }

    if (arr == NULL || size == 0)
    {
        if (buffer_size >= 3)
        {
            strcpy(buffer, "[]");
            return 2;
        }
        return -1;
    }

    size_t pos = 0;
    if (pos < buffer_size - 1)
    {
        buffer[pos++] = '[';
    }

    for (uint8_t i = 0; i < size && pos < buffer_size - 1; i++)
    {
        char num_buf[8];
        int len = snprintf(num_buf, sizeof(num_buf), "%d", arr[i]);

        for (int j = 0; j < len && pos < buffer_size - 1; j++)
        {
            buffer[pos++] = num_buf[j];
        }

        if (i < size - 1 && pos < buffer_size - 2)
        {
            buffer[pos++] = ',';
            buffer[pos++] = ' ';
        }
    }

    if (pos < buffer_size - 1)
    {
        buffer[pos++] = ']';
    }
    buffer[pos] = '\0';

    return (int)pos;
}

